proof.r:
suppressPackageStartupMessages(library(mvtnorm))
fmt <- function(x) {
  if (is.logical(x) && length(x) == 1) return(if (isTRUE(x)) "1" else "0")
  paste(sprintf("%.16g", as.numeric(x)), collapse = " ")
}
one <- function() {
  as.numeric(dmvnorm(c(0, 0)))
}
value <- one()
elapsed <- numeric(20)
for (i in seq_len(20)) {
  t0 <- as.numeric(Sys.time())
  one()
  elapsed[[i]] <- as.numeric(Sys.time()) - t0
}
cat(fmt(value), "\n", sep = "")
cat(sprintf("MS %.17g\n", median(elapsed) * 1000))

proof.python:
import math
import statistics
import time
import numpy as np
from boot.rng import set_seed
from mvtnorm import *

def flat(x):
    if isinstance(x, (bool, np.bool_)):
        return np.array([1.0 if x else 0.0])
    return np.atleast_1d(np.asarray(x, dtype=float)).ravel(order="F")

def one():
    return flat(dmvnorm([0.0, 0.0]))

value = one()
elapsed = []
for _ in range(20):
    started = time.perf_counter()
    one()
    elapsed.append((time.perf_counter() - started) * 1000)
print(" ".join(f"{v:.16g}" for v in flat(value)))
print(f"MS {statistics.median(elapsed):.17g}")

